:root {
  --bg: #0B0414;
  --surface: #140A24;
  --text: #F4F0FF;
  --primary: #7C5CFF;
  --accent: #22D3EE;
  --muted: #C9C0E0;
  --font-ui: Inter, system-ui, sans-serif;
  --font-display: Inter, system-ui, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-ui);
  line-height: 1.5;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}

import type { Metadata } from "next";
import type { ReactNode } from "react";
import "./globals.css";

export const metadata: Metadata = {
  title: "Membership | Fix your bike, together",
  description: "Stands, tools and know-how, free on Saturdays.",
};

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

.main {
  max-width: 64rem;
  margin: 0 auto;
  padding: 2rem 1rem 4rem;
}

.hero {
  text-align: center;
  padding: 3rem 0 2rem;
}

.hero h1 {
  font-family: var(--font-display);
  font-size: clamp(2rem, 7vw, 3.5rem);
  line-height: 1.1;
  margin: 0 0 1rem;
}

.hero p {
  color: var(--muted);
  font-size: 1.125rem;
  margin: 0;
}

.features {
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  margin-bottom: 3rem;
}

.card {
  background: var(--surface);
  border-radius: 1rem;
  padding: 1.5rem;
  border: 1px solid rgba(124, 92, 255, 0.35);
}

.card h2 {
  margin: 0 0 0.5rem;
  color: var(--accent);
  font-size: 1.25rem;
}

.card p {
  margin: 0;
  color: var(--muted);
}

"use client";

import { useState } from "react";
import styles from "./Pricing.module.css";

type Billing = "monthly" | "yearly";

interface Tier {
  name: string;
  monthly: number;
  yearly: number;
  blurb: string;
  featured: boolean;
}

// Placeholder tiers and prices: replace with the co-op's real plans.
const TIERS: Tier[] = [
  { name: "Supporter", monthly: 5, yearly: 50, blurb: "Back the workshop and join Saturday sessions.", featured: false },
  { name: "Member", monthly: 12, yearly: 120, blurb: "Open workshop access with a volunteer beside you.", featured: true },
  { name: "Household", monthly: 20, yearly: 200, blurb: "Everyone at your address, one membership.", featured: false },
];

export default function Pricing() {
  const [billing, setBilling] = useState<Billing>("monthly");
  const isYearly = billing === "yearly";

  return (
    <section aria-labelledby="pricing-title" className={styles.section}>
      <h2 id="pricing-title" className={styles.title}>
        Membership
      </h2>

      <div className={styles.toggle} role="group" aria-label="Billing period">
        <button
          type="button"
          aria-pressed={!isYearly}
          className={styles.toggleBtn}
          onClick={() => setBilling("monthly")}
        >
          Monthly
        </button>
        <button
          type="button"
          aria-pressed={isYearly}
          className={styles.toggleBtn}
          onClick={() => setBilling("yearly")}
        >
          Yearly
        </button>
      </div>

      <ul className={styles.grid}>
        {TIERS.map((tier) => (
          <li
            key={tier.name}
            className={tier.featured ? styles.featured : styles.tier}
          >
            <h3>{tier.name}</h3>
            <p className={styles.blurb}>{tier.blurb}</p>
            <p className={styles.price} aria-live="polite">
              <span className={styles.amount}>
                ${isYearly ? tier.yearly : tier.monthly}
              </span>
              <span className={styles.per}>{isYearly ? " / year" : " / month"}</span>
            </p>
            <a className={styles.cta} href="#join">
              Join as {tier.name}
            </a>
          </li>
        ))}
      </ul>
    </section>
  );
}

.section {
  text-align: center;
}

.title {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 5vw, 2.25rem);
  margin: 0 0 1.5rem;
}

.toggle {
  display: inline-flex;
  background: var(--surface);
  border: 1px solid var(--primary);
  border-radius: 999px;
  padding: 0.25rem;
  margin-bottom: 2rem;
}

.toggleBtn {
  background: transparent;
  color: var(--text);
  border: 0;
  border-radius: 999px;
  padding: 0.6rem 1.4rem;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  min-height: 44px;
  transition: background 0.2s;
}

.toggleBtn[aria-pressed="true"] {
  background: #5B3BE0;
  color: #FFFFFF;
}

.grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  text-align: left;
}

.tier,
.featured {
  background: var(--surface);
  border-radius: 1rem;
  padding: 1.5rem;
  border: 1px solid rgba(124, 92, 255, 0.35);
  display: flex;
  flex-direction: column;
}

.featured {
  border: 2px solid var(--accent);
}

.tier h3,
.featured h3 {
  margin: 0 0 0.5rem;
  font-size: 1.25rem;
}

.blurb {
  color: var(--muted);
  margin: 0 0 1rem;
  flex: 1;
}

.price {
  margin: 0 0 1rem;
}

.amount {
  font-size: 2.25rem;
  font-weight: 700;
}

.per {
  color: var(--muted);
}

.cta {
  display: block;
  text-align: center;
  background: #5B3BE0;
  color: #FFFFFF;
  text-decoration: none;
  font-weight: 600;
  padding: 0.75rem 1rem;
  border-radius: 0.6rem;
}

.cta:hover {
  background: #6D4FF0;
}
